/* --- 33-quota.js --- */
/* Plans and personal detail. Canonical quota and local-time resolution stay server-side.
   Byte semantics are exact and unchanged: GB = 1,000,000,000 B and GiB = 1,073,741,824 B.
   The form uses one unlimited checkbox, a numeric input and one native scrolling unit selector. */
function quotaLabel(q) {
  const s=q?.status||'unavailable', names={active:bi('Active','使用中'),pending_reconciliation:bi('Updating usage…','正在更新用量…'),quota_exceeded:bi('Data used up','數據已用完'),expired:bi('Service ended','服務已到期'),manually_disabled:bi('Paused','已暫停'),protected_legacy:bi('Shared original account','共用原有帳戶'),unavailable:bi('Unavailable','無法取得')};
  return status(s==='active'?'ok':s==='protected_legacy'?'locked':'warning',names[s]||s);
}
const QUOTA_UNITS={B:1,KB:1000,KiB:1024,MB:1e6,MiB:1048576,GB:1e9,GiB:1073741824,TB:1e12,TiB:1099511627776};
