function normalizeSearch(text){return String(text||'').toLocaleLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g,'').replace(/[_/·,()]/g,' ').replace(/\s+/g,' ').trim();}
function offsetQuery(text){const m=String(text).trim().toLowerCase().replace('−','-').match(/^(?:utc|gmt)?\s*([+-])\s*(\d{1,2})(?::?(\d{2}))?$/);if(!m)return null;return 'UTC'+m[1]+m[2].padStart(2,'0')+':'+(m[3]||'00');}
