  if(state.zoneIndex&&state.zoneIndex.lang===state.lang&&state.zoneIndex.data===state.timezoneData)return state.zoneIndex.rows;
  const rows=timezones().map(zone=>{const offset=zoneOffset(zone);const words=[zone,zoneCity(zone,'en'),zoneCity(zone,'zh-Hant-HK'),zoneCountry(zone,'en'),zoneCountry(zone,'zh-Hant-HK'),zoneGeneric(zone,'en'),zoneGeneric(zone,'zh-Hant-HK'),offset,offset.replace('UTC','GMT')];return {zone,offset,label:zoneFriendly(zone),city:normalizeSearch(zoneCity(zone,locale())),hay:normalizeSearch(words.join(' | '))};});
