function quotaDisplay(n){if(!n)return {amount:'100',unit:'GB'};for(const unit of ['TB','TiB','GB','GiB','MB','MiB','KB','KiB']){const value=n/QUOTA_UNITS[unit],s=value.toFixed(6).replace(/\.?0+$/,'');if(value>=1&&Number(s)*QUOTA_UNITS[unit]===n)return {amount:s,unit};}return {amount:String(n),unit:'B'};}
