      if(['ArrowDown','ArrowUp','PageDown','PageUp'].includes(event.key)){event.preventDefault();if(!open){showZones(zoneInput.value===timezoneLabel(el('timezone').value)?'':zoneInput.value);return;}if(!zoneOptions.length)return;const step={ArrowDown:1,ArrowUp:-1,PageDown:page,PageUp:-page}[event.key];zoneActive=Math.min(zoneOptions.length-1,Math.max(0,zoneActive+step));markActive();}
      else if(open&&(event.key==='Home'||event.key==='End')&&event.ctrlKey){event.preventDefault();zoneActive=event.key==='Home'?0:zoneOptions.length-1;markActive();}
