  const [row,history,,users]=await Promise.all([api('accounting/user?id='+encodeURIComponent(id)),api('accounting/history?id='+encodeURIComponent(id)+'&window=30d'),ensureTimezones(),state.users?Promise.resolve(state.users):api('users')]);
