async function userWizard(){const version=++modalGeneration;const [accounting,users]=await Promise.all([api('accounting'),state.users?Promise.resolve(state.users):api('users'),ensureTimezones()]);if(version!==modalGeneration)return;state.accounting=accounting;state.users=users;modal(bi('Create VPN user','新增 VPN 使用者'),`<form id="new-user-wizard"><div class="wizard-progress" aria-label="${esc(bi('Steps','步驟'))}">${[bi('1 Identity','1 身分'),bi('2 Plan','2 方案'),bi('3 Personal access','3 個人存取')].map((x,i)=>`<span data-step-label="${i}" ${i===0?'aria-current="step"':''}>${esc(x)}</span>`).join('')}</div><section class="wizard-step" data-step="0">${field('name',bi('Display name','顯示名稱'),'','text','required maxlength="64" pattern="[A-Za-z0-9._\\-]{1,64}" autofocus')}${field('tags',bi('Tags · optional, comma separated','標籤 · 可選，以逗號分隔'))}<fieldset><legend>${esc(bi('Enabled protocols','啟用協定'))}</legend>${(state.users?.find(u=>u.protected)?.protocols||Object.keys(PROTOCOL_NAMES)).map(p=>checkbox('',PROTOCOL_NAMES[p],true,`data-new-protocol value="${esc(p)}"`)).join('')}</fieldset><p class="hint">${esc(bi('Each user receives independent VPN credentials.','每位使用者會獲派獨立 VPN 憑證。'))}</p></section><section class="wizard-step" data-step="1" hidden>${state.accounting?.enabled?quotaFields():`<p class="notice warning">${esc(bi('Turn on usage tracking before setting data allowances.','設定數據用量前，請先開啟用量追蹤。'))}</p>`}</section><section class="wizard-step" data-step="2" hidden>${checkbox('portal_enabled',bi('Enable a separate personal portal login','啟用獨立的個人入口登入'))}${field('portal_username',bi('Portal username','入口使用者名稱'),'','text','autocomplete="off"')}${field('portal_password',bi('Initial portal password','入口初始密碼'),'','password','autocomplete="new-password" minlength="14"')}${btn('portal-generate',bi('Generate a strong password','產生強密碼'))}<p class="muted">${esc(bi('The user changes the initial password at first login. VPN credentials and portal credentials are separate.','使用者首次登入時須更改初始密碼，個人入口同 VPN 憑證分開。'))}</p><p class="notice">${esc(bi('Next you will review the exact plan, enabled protocols and any restart before creating this user. A repeatable private connection link is created together.','下一步會檢視確實方案、啟用的協定及是否需要重新啟動，然後建立使用者，同時建立日後可再取得的私人連結。'))}</p></section><div class="actions end">${btn('wizard-back',bi('Back','上一步'),'','hidden')}${btn('wizard-next',bi('Next','下一步'),'primary')}<button type="submit" class="primary" id="wizard-review" hidden>${esc(bi('Review creation','檢視建立內容'))}</button></div></form>`);state.wizardStep=0;}
