function bindNetworkForm(){const f=$('#network-form');if(!f)return;const mode=f.elements.namedItem('mode');const unavailable={ipv4:!state.network.server.ipv4&&!state.network.addresses.some(a=>a.family===4&&a.global_unicast),ipv6:!state.network.addresses.some(a=>a.family===6&&a.usable&&!['::1'].includes(a.address)),dual:!state.network.addresses.some(a=>a.family===6&&a.usable&&!['::1'].includes(a.address))};Array.from(mode.options).forEach(o=>{if(unavailable[o.value]&&o.value!==mode.value){o.disabled=true;o.textContent+=' · '+bi('address unavailable','位址未提供');}});mode.onchange=()=>{$('#network-advanced').hidden=mode.value!=='advanced';};}
async function submitNetwork(form){const v=Object.fromEntries(new FormData(form)),d={};if(v.mode==='preserve'){toast(bi('Existing behavior retained','已保留既有行為'));return;}Object.assign(d,{scope:v.scope,ipv4:v.ipv4.trim(),ipv6:v.ipv6.trim(),endpoint_override:v.endpoint_override.trim()});
 if(v.mode==='advanced'){d.policies=Object.fromEntries(['inbound','egress','dns','client'].map(k=>[k,v[k]]));d.panel_family=v.panel_family;if(v.listen.trim())d.listen=v.listen.trim();d.interface=v.interface.trim();if(v.fallback_delay_ms.trim())d.fallback_delay_ms=Number(v.fallback_delay_ms);else d.fallback_delay_ms=null;const ue={};if(form.elements.udp_prefer_ipv6.checked)ue.prefer_ipv6=true;if(form.elements.udp_reject_quic.checked)ue.reject_quic=true;d.udp_egress=Object.keys(ue).length?ue:null;}
 else {d.mode=v.mode;d.fallback_delay_ms=null;if(v.match_https)d.panel_family=v.mode;}
 await prepareChange({kind:'network',data:d},form.querySelector('button[type=submit]'));
}

pages.network.after=bindNetworkForm;
